# name: lag1_response_autocorrelation
# description: Pearson correlation between a response and the same participant's immediately preceding response (consecutive trial_index); observed above the null means people show sequential yes/no carryover (perseveration) the trial-independent model fails to produce, below means alternation it fails to produce.
def test_statistic(df):
    r = df["rating"].astype(float).to_numpy()
    ti = df["trial_index"].astype(int).to_numpy()
    ok = np.diff(ti) == 1
    a, b = r[:-1][ok], r[1:][ok]
    if len(a) < 3 or a.std() == 0 or b.std() == 0:
        return 0.0
    return float(np.corrcoef(a, b)[0, 1])

# name: late_minus_early_yes_rate
# description: Yes-rate in the second half of each session (trial_index >= 225) minus the first half; a positive/negative observed value beyond the null means people drift toward more/fewer yeses over the session, a drift the stationary model does not produce.
def test_statistic(df):
    r = df["rating"].astype(float).to_numpy()
    ti = df["trial_index"].astype(int).to_numpy()
    late = ti >= 225
    if late.sum() == 0 or (~late).sum() == 0:
        return 0.0
    return float(r[late].mean() - r[~late].mean())

# name: example_target_yes_rate
# description: Yes-rate on trials whose target is itself one of the shown examples; observed above the model's null means the model under-produces yeses to the examples (its noise/gain/bias leak too much belief away from seen numbers), below means it over-produces them.
def test_statistic(df):
    ex = df["number_set"].astype(str).str.split(",", expand=True).apply(pd.to_numeric, errors="coerce").to_numpy(dtype=float)
    t = df["target"].astype(float).to_numpy()
    is_ex = (ex == t[:, None]).any(axis=1)
    r = df["rating"].astype(float).to_numpy()
    if is_ex.sum() == 0:
        return 0.0
    return float(r[is_ex].mean())
